-- The model constants per input file, in their own schema (folder) Constraints: edit them through
-- the view [Constraints].[BPL_Constraints] (SELECT / INSERT / UPDATE / DELETE), one row per File_Name and Field_Index.
-- Value is the Model sheet's value: percentages as fractions (0.7 = 70%), dates as yyyy-mm-dd.
-- The rows are in the app's table dbo.[ConstraintValues], which the app reads and writes; its Constraints
-- page logs each value it applies in dbo.[ConstraintChanges]. Run after the app's deployment created
-- dbo.[ConstraintValues]. Safe to rerun.
-- Generated by packages/frontend/scripts/gen-constraints.ts.

SET XACT_ABORT ON;
IF SCHEMA_ID('Constraints') IS NULL EXEC('CREATE SCHEMA [Constraints] AUTHORIZATION [dbo]');
GO
-- An earlier version kept the rows in a table [Constraints].[BPL_Constraints] with triggers: move them into dbo.[ConstraintValues].
IF OBJECT_ID('[Constraints].[BPL_Constraints]', 'U') IS NOT NULL
BEGIN
  BEGIN TRANSACTION;
  EXEC('INSERT INTO dbo.[ConstraintValues] ([File_Name], [Field_Index], [Field_Name_Display], [Value])
    SELECT t.[File_Name], t.[Field_Index], t.[Field_Name_Display], t.[Value] FROM [Constraints].[BPL_Constraints] AS t
    WHERE NOT EXISTS (SELECT 1 FROM dbo.[ConstraintValues] AS c WHERE c.[File_Name] = t.[File_Name] AND c.[Field_Index] = t.[Field_Index])');
  DROP TABLE [Constraints].[BPL_Constraints];
  COMMIT;
END
DROP TRIGGER IF EXISTS dbo.[trg_ConstraintChanges_apply];
DELETE FROM dbo.[LookupCaches] WHERE [Table_Name] = N'BPL_Constraints';
GO
CREATE OR ALTER VIEW [Constraints].[BPL_Constraints] AS
SELECT [File_Name], [Field_Index], [Field_Name_Display], [Value] FROM dbo.[ConstraintValues];
GO
