-- Input files the loader adds later start with the defaults.
IF OBJECT_ID('dbo.[Input_files]', 'U') IS NOT NULL
  EXEC('CREATE OR ALTER TRIGGER dbo.[trg_Input_files_constraints] ON dbo.[Input_files] AFTER INSERT AS
BEGIN
  SET NOCOUNT ON;
  INSERT INTO dbo.[ConstraintValues] ([File_Name], [Field_Index], [Field_Name_Display], [Value])
  SELECT f.[File_Name], d.[Field_Index], d.[Field_Name_Display], d.[Value]
  FROM (SELECT DISTINCT [File_Name] FROM inserted) AS f CROSS JOIN [Constraints].[BPL_Constraints_Defaults] AS d
  WHERE NOT EXISTS (SELECT 1 FROM dbo.[ConstraintValues] AS c WHERE c.[File_Name] = f.[File_Name] AND c.[Field_Index] = d.[Field_Index]);
END');
GO
-- The input files loaded so far (and any field added since a file was filled).
INSERT INTO dbo.[ConstraintValues] ([File_Name], [Field_Index], [Field_Name_Display], [Value])
SELECT f.[File_Name], d.[Field_Index], d.[Field_Name_Display], d.[Value]
FROM (SELECT DISTINCT [File_Name] FROM dbo.[InputLoans]) AS f CROSS JOIN [Constraints].[BPL_Constraints_Defaults] AS d
WHERE NOT EXISTS (SELECT 1 FROM dbo.[ConstraintValues] AS c WHERE c.[File_Name] = f.[File_Name] AND c.[Field_Index] = d.[Field_Index]);
GO
